Action: plot_chart({'query': "\nWITH veg AS (\n  SELECT DISTINCT e.gmap_id, e.name, e.avg_rating, e.num_of_reviews\n  FROM establishment_categories ec\n  JOIN category c ON c.category_id = ec.category_id\n  JOIN establishments e ON e.gmap_id = ec.gmap_id\n  WHERE lower(c.category) IN ('vegetarian restaurant','vegetarian cafe and deli','vegan restaurant')\n    AND ST_Y(e.geom) BETWEEN 40.40 AND 40.82\n    AND ST_X(e.geom) BETWEEN -112.20 AND -111.65\n    AND e.num_of_reviews >= 40\n)\nSELECT name, avg_rating, num_of_reviews\nFROM veg\nORDER BY avg_rating DESC, num_of_reviews DESC\nLIMIT 10\n", 'chart_type': 'bar', 'x': 'name', 'y': 'avg_rating', 'color': 'num_of_reviews', 'title': 'Top Vegetarian/Vegan Restaurants in Salt Lake County by Rating'})

